# First, let me load all grids available for this instance
import os, re

def load_grids():
    session_dir = os.environ.get('RLM_SESSION_DIR', '')
    if not session_dir:
        print("No RL Session dir found")
        return {}

    sessions_path = os.path.join(session_dir, '../../sessions')
    try:
        jsonl_path = os.path.join(sessions_path, os.path.basename(session_dir) + '.jsonl')
        with open(jsonl_path, 'r') as f:
            text = f.read().replace('\\n', '\n')

        G = {}
        pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
        for m in re.finditer(pattern, text):
            k = m[1]
            h, w = int(m[2]), int(m[3])
            start_pos = m.end()

            # Extract rows from the match
            lines = []
            remaining = text[start_pos:]
            for line in remaining.split('\n')[:h]:
                if line.strip():
                    lines.append(line)

            if k not in G and all(len(r) == w and all(c.isdigit() for c in r) for r in lines):
                G[k] = [[int(c) for c in row] for row in lines]

        return G
    except FileNotFoundError:
        print(f"Sessions file not found at {jsonl_path}")
        return {}

G = load_grids()
print("Available grids:", sorted(G.keys()))
for k, v in G.items():
    print(f"\n{v}")

